def parse_string(parser):
    # Parse string starting at STRING_DQ_START or STRING_IND_START, until matching END, collecting interp exprs.
    # Assumes current peek is START, consumes it, then collects parts until END.
    # Parts: CONTENT tokens are skipped (already filtered? Actually CONTENT filtered out, so parser.toks doesn't contain CONTENT. Good. So inside string, significant tokens are INTERP_START, ... (expr tokens), INTERP_END, and STRING_END.
    # But need to handle nested strings inside interp (which are parsed via parse_expr which will call parse_string recursively). Good.
    # So here, just need to consume START, then loop: if next is INTERP_START, consume, parse expr, expect INTERP_END, add to parts; elif next is STRING_END (matching type?), consume and break; else error? Actually there should be no other significant tokens inside string (since CONTENT filtered). Good. But what about unterminated string (EOF before END)? Then error.
    start_tok = parser.peek()
    if not start_tok or start_tok.typ not in ('STRING_DQ_START', 'STRING_IND_START'):
        raise ParseError("expected string start")
    is_dq = (start_tok.typ == 'STRING_DQ_START')
    parser.consume()  # START
    parts = []
    while True:
        nxt = parser.peek()
        if not nxt:
            raise ParseError("unexpected end of file")
        if nxt.typ == 'INTERP_START':
            parser.consume()
            expr = parse_expr(parser)
            parser.expect('INTERP_END', 'TOKEN_RBRACE')
            parts.append((True, expr))
            continue
        if is_dq and nxt.typ == 'STRING_DQ_END':
            parser.consume()
            break
        if (not is_dq) and nxt.typ == 'STRING_IND_END':
            parser.consume()
            break
        # Unexpected (e.g., wrong END type? Like DQ_START with IND_END? That would be mismatched (should not happen since lexer correctly pairs? Actually lexer pairs correctly (dq start with dq end, ind start with ind end), so mismatch shouldn't occur. Unless nested? No.
        # Also, what about RBRACE (from interp depth? No, INTERP_END is distinct from RBRACE. Good.)
        raise ParseError(f"unexpected {token_to_rnix(nxt.typ)} at {nxt.start}..{nxt.end}", nxt)
    return StringNode(parts)

def parse_or(parser):
    # Handle 'or' keyword (select-or default, but treat as binary low precedence)
    left = parse_binary(parser)
    while True:
        t = parser.peek()
        if t and t.typ == 'OR':
            # 'or' as binary: consume and parse right as parse_binary? Or parse_or (right-assoc)? For a or b or c, right-assoc? Doesn't matter for liveness (all traversed). Use right as parse_binary (or parse_or for right-assoc? Let's use parse_binary for left-assoc? Actually for liveness, either fine. Use parse_binary to avoid infinite? No, parse_or calling parse_binary for right is fine (left-assoc). For right-assoc, call parse_or recursively. Let's do left-assoc (while loop).
            parser.consume()
            right = parse_binary(parser)
            left = BinOpNode('or', left, right)
            continue
        break
    return left

def parse_binary(parser):
    # Parse binary ops with same precedence (left-assoc), all operators: ||, &&, ==, !=, <, <=, >, >=, ++, //, +, -, *, /
    # Note: // (update) is binary, ++ (concat), etc.
    # Also need to handle ! (unary) and - (unary) in parse_unary, not here.
    left = parse_unary(parser)
    while True:
        t = parser.peek()
        if not t:
            break
        op = None
        if t.typ == 'OP_OR':
            op = '||'
        elif t.typ == 'OP_AND':
            op = '&&'
        elif t.typ == 'OP_EQ':
            op = '=='
        elif t.typ == 'OP_NEQ':
            op = '!='
