def parse_atom(parser):
    t = parser.peek()
    if not t:
        raise ParseError("unexpected end of file")
    if t.typ == 'IDENT':
        parser.consume()
        return VarNode(t.text, t)
    if t.typ in ('NUMBER', 'PATH'):
        parser.consume()
        return LitNode(t)
    if t.typ in ('STRING_DQ_START', 'STRING_IND_START'):
        return parse_string(parser)
    if t.typ == 'LPAREN':
        parser.consume()
        expr = parse_expr(parser)
        parser.expect('RPAREN', 'TOKEN_R_PAREN')
        return ParenNode(expr)
    if t.typ == 'LBRACK':
        parser.consume()  # [
        elems = []
        while True:
            nxt = parser.peek()
            if not nxt:
                raise ParseError("unexpected end of file, wanted any of [TOKEN_R_BRACK]")
            if nxt.typ == 'RBRACK':
                parser.consume()
                break
            # List elem is full expr? Yes (can be let, if, etc.)
            elem = parse_expr(parser)
            elems.append(elem)
            # No separators (whitespace only, already filtered). Continue until ].
            continue
        return ListNode(elems)
    if t.typ == 'LBRACE':
        # Attrset (since pattern lambda already handled in parse_lambda, here it's attrset)
        # Could also be empty? Handled.
        return parse_attrset(parser, is_rec=False, rec_tok=None)
    if t.typ == 'REC':
        rec_tok = parser.consume()
        # Expect LBRACE
        nxt = parser.peek()
        if not nxt or nxt.typ != 'LBRACE':
