    raise ParseError(f"unexpected {token_to_rnix(t.typ)} at {t.start}..{t.end}", t)

def parse_attrset(parser, is_rec, rec_tok):
    lbrace = parser.expect('LBRACE', 'TOKEN_L_BRACE')
    entries = []
    while True:
        nxt = parser.peek()
        if not nxt:
            raise ParseError("unexpected end of file, wanted any of [TOKEN_R_BRACE]")
        if nxt.typ == 'RBRACE':
            rbrace = parser.consume()
            break
        if nxt.typ == 'INHERIT':
            inherit_tok = parser.consume()
            source = None
            lparen = None
            rparen = None
            peek2 = parser.peek()
            if peek2 and peek2.typ == 'LPAREN':
                lparen = parser.consume()
                source = parse_expr(parser)
                rparen = parser.expect('RPAREN', 'TOKEN_R_PAREN')
            names = []
            first = parser.peek()
            if not first or first.typ != 'IDENT':
                if first is None:
                    raise ParseError("unexpected end of file, wanted any of [TOKEN_IDENT]")
                else:
                    raise ParseError(f"unexpected {token_to_rnix(first.typ)} at {first.start}..{first.end}, wanted any of [TOKEN_IDENT]", first)
            while True:
                nt = parser.peek()
                if nt and nt.typ == 'IDENT':
                    names.append((nt.text, nt))
                    parser.consume()
                else:
                    break
            semi = parser.expect('SEMICOLON', 'TOKEN_SEMICOLON')
            entries.append(('inherit', source, names, inherit_tok, lparen, rparen, semi))
            continue
        else:
            # Attrpath = expr ;
            # Similar to let attrpath parsing (with dynamic handling)
            comp_list = []
            ft = parser.peek()
            if not ft:
                raise ParseError("unexpected end of file, wanted any of [TOKEN_IDENT]")
            if ft.typ == 'IDENT':
                comp_list.append(('ident', ft))
                parser.consume()
            elif ft.typ in ('STRING_DQ_START', 'STRING_IND_START'):
                str_node = parse_string(parser)
                comp_list.append(('string', str_node))
            elif ft.typ == 'INTERP_START':
                parser.consume()
                expr_inside = parse_expr(parser)
                parser.expect('INTERP_END', 'TOKEN_RBRACE')
                comp_list.append(('interp', expr_inside))
            elif ft.typ == 'NUMBER':
                comp_list.append(('number', ft))
                parser.consume()
            else:
                raise ParseError(f"unexpected {token_to_rnix(ft.typ)} at {ft.start}..{ft.end}, wanted any of [TOKEN_IDENT]", ft)
            while True:
                dot = parser.peek()
                if dot and dot.typ == 'DOT':
                    parser.consume()
                    nxt_attr = parser.peek()
                    if not nxt_attr:
                        raise ParseError("unexpected end of file, wanted any of [TOKEN_IDENT]")
                    if nxt_attr.typ == 'IDENT':
                        comp_list.append(('ident', nxt_attr))
                        parser.consume()
                    elif nxt_attr.typ in ('STRING_DQ_START', 'STRING_IND_START'):
                        str_node2 = parse_string(parser)
                        comp_list.append(('string', str_node2))
                    elif nxt_attr.typ == 'INTERP_START':
                        parser.consume()
                        expr2 = parse_expr(parser)
                        parser.expect('INTERP_END', 'TOKEN_RBRACE')
                        comp_list.append(('interp', expr2))
                    elif nxt_attr.typ == 'NUMBER':
                        comp_list.append(('number', nxt_attr))
                        parser.consume()
                    elif nxt_attr.typ in ('OR', 'IF', 'THEN', 'ELSE', 'ASSERT', 'WITH', 'LET', 'IN', 'REC', 'INHERIT'):
                        comp_list.append(('keyword_attr', nxt_attr))
                        parser.consume()
                    else:
                        raise ParseError(f"unexpected {token_to_rnix(nxt_attr.typ)} at {nxt_attr.start}..{nxt_attr.end}, wanted any of [TOKEN_IDENT]", nxt_attr)
                    continue
                break
            assign_tok = parser.expect('ASSIGN', 'TOKEN_ASSIGN')
            val = parse_expr(parser)
            semi = parser.expect('SEMICOLON', 'TOKEN_SEMICOLON')
            entries.append(('attr', comp_list, val, assign_tok, semi))
            continue
    return AttrSetNode(is_rec, entries, lbrace, rbrace if 'rbrace' in locals() else None)

