def perform_edits_for_file(fp, content_str, results, config, tokens_for_comments=None):
    if not results:
        return (content_str, True)
    n = len(content_str)
    byte_offsets = [0]*(n+1)
    b = 0
    for i, ch in enumerate(content_str):
        byte_offsets[i] = b
        b += len(ch.encode('utf-8'))
    byte_offsets[n] = b
    byte_to_char = {bo:i for i, bo in enumerate(byte_offsets)}
    import bisect
    def b2c(bo):
        if bo in byte_to_char:
            return byte_to_char[bo]
        idx = bisect.bisect_right(byte_offsets, bo) - 1
        return max(0, min(n, idx))
    from collections import defaultdict
    scope_to_reported = defaultdict(list)
    scope_objs = {}
    for (line, col, end_col, msg, edit_info) in results:
        sc = edit_info['scope']
        idx = edit_info['idx']
        scope_to_reported[id(sc)].append(idx)
        scope_objs[id(sc)] = sc
    if tokens_for_comments is None:
        try:
