        to_remove = set([i for i in reported_idxs if i < m])
        if not to_remove:
            continue
        trailing_start = m
        for i in range(m-1, -1, -1):
            if i in to_remove:
                trailing_start = i
            else:
                break
        trailing_size = m - trailing_start if trailing_start < m else 0
        if trailing_size < 2:
            continue
        if pat_info.get('ellipsis'):
            continue
        last_entry = entries[m-1]
        if last_entry.get('comma_after') is not None:
            continue
        first_dead_tok = entries[trailing_start]['token']
        first_dead_start = first_dead_tok.start
        rbrace_tok = pat_info.get('rbrace')
